256	/// Validates an intent while placing its workspace lock under an explicit
257	/// caller-owned state directory.
258	///
259	/// CI callers that supply an explicit durable state file must use its parent
260	/// here as well.  Otherwise validation would still depend on the runner's
261	/// implicit platform state location, defeating hermetic job handoff.
262	pub fn validate_release_intent_with_state_directory<'a, L: ProjectLocator, R: CommandRunner>(
263	    root: &Path,
264	    locator: &L,
265	    runner: &'a R,
266	    state_directory: Option<&Path>,
267	    received: ReleaseIntentV1,
268	) -> Result<ValidatedReleaseIntent<'a>, GraphError> {
269	    let root = canonical_root(root)?;
270	    let workspace = Workspace::load(root.clone(), locator, runner)?;
271	    let initial_trust = observe_git_trust(&workspace, received.trust_profile)?;
272	    let lock = ReleaseWorkspaceLock::acquire(&root, state_directory)?;
273	    let trust = observe_git_trust(&workspace, received.trust_profile)?;
274	    if trust != initial_trust {
275	        return Err(GraphError::ReleaseIntentStale {
276	            reason: StaleReason::trust_evidence_changed(),
277	        });
278	    }
279	    let source = source_from_trust(&trust);
280	    let (expected, prepared) =
281	        derive_release_intent_with_prepared(&workspace, &received.decision, source.clone(), received.trust_profile)?;
282	    let final_trust = observe_git_trust(&workspace, received.trust_profile)?;
283	    if expected != received || final_trust != trust {
284	        return Err(GraphError::ReleaseIntentStale {
285	            reason: StaleReason::intent_differs_from_fresh_derivation(),
286	        });
287	    }
288	
289	    Ok(ValidatedReleaseIntent {
290	        prepared: PreparedReleaseInputs {
291	            root,
292	            source,
293	            trust: final_trust,
294	            git_remote: prepared.git_remote,
295	            _lock: lock,
296	            operations: prepared.operations,
297	        },
298	        intent: received,
299	        runner,
300	    })
301	}
