317	fn observe_git_trust<R: CommandRunner, D: DependencyResolver>(
318	    workspace: &Workspace<'_, R, D>,
319	    trust_profile: ExecutionTrustProfileV1,
320	) -> Result<GitCommitTrustEvidence, GraphError> {
321	    if !matches!(trust_profile, ExecutionTrustProfileV1::GitCommit) {
322	        return Err(GraphError::ReleaseIntentStale {
323	            reason: StaleReason::legacy_unclassified(),
324	        });
325	    }
326	    let evidence = workspace.git_access().observe_git_commit_trust()?;
327	    if evidence.canonical_root() != workspace.root || evidence.head_disposition() != GitHeadDisposition::Detached {
328	        return Err(GraphError::ReleaseIntentStale {
329	            reason: StaleReason::legacy_unclassified(),
330	        });
331	    }
332	    Ok(evidence)
333	}
