422	                        reason: StaleReason::legacy_unclassified(),
423	                    });
424	                };
425	                let built = self.run_argv(build)?;
426	                if built.exit_code != Some(0) {
427	                    return Err(GraphError::ReleaseIntentStale {
428	                        reason: StaleReason::legacy_unclassified(),
429	                    });
430	                }
431	                self.run_argv(upload)?
432	            }
433	            _ => {
434	                return Err(GraphError::ReleaseIntentStale {
435	                    reason: StaleReason::legacy_unclassified(),
436	                })
437	            }
438	        };
439	        let outcome = match id.package.ecosystem() {
440	            Ecosystem::Cargo => registry_argv::classify_cargo_output(&output),
441	            Ecosystem::Npm => registry_argv::classify_npm_publish_output(&output),
442	            Ecosystem::Pypi => registry_argv::classify_twine_output(&output),
443	            _ => {
444	                return Err(GraphError::ReleaseIntentStale {
445	                    reason: StaleReason::legacy_unclassified(),
446	                })
447	            }
448	        }
449	        .map_err(|_error| GraphError::ReleaseIntentStale {
450	            reason: StaleReason::legacy_unclassified(),
451	        })?;
452	        if matches!(id.package.ecosystem(), Ecosystem::Npm) && matches!(outcome, PublishOutcome::Published) {
453	            let is_published = self.npm_version_is_published(package_name, version, registry.endpoint.as_deref())?;
454	            require_registry_confirmation(is_published, package_name, version)?;
455	        }
456	        Ok(match outcome {
457	            PublishOutcome::Published => OperationOutcome::Published,
458	            PublishOutcome::AlreadyPublished => OperationOutcome::AlreadySatisfied,
459	        })
460	    }
461	}
