463	/// A successful npm publish client process is not a receipt: this checks
464	/// whether the registry itself has caught up before the operation is
465	/// considered done. If it hasn't, the operation must remain `Attempting`
466	/// for reconciliation rather than asserting a release the registry cannot
467	/// yet prove exists -- and the error reported must say exactly that (a
468	/// successful publish awaiting registry propagation), not the unrelated
469	/// "no release operation was authorized" claim `GraphError::ReleaseIntentStale`
470	/// makes, which would be false here.
471	fn require_registry_confirmation(is_published: bool, package: &str, version: &Version) -> Result<(), GraphError> {
472	    if is_published {
473	        return Ok(());
474	    }
475	    Err(GraphError::RegistryPublishUnconfirmed {
476	        package: package.to_string(),
477	        version: version.clone(),
478	    })
479	}
