481	impl ValidatedReleaseIntent<'_> {
482	    /// Runs a [`registry_argv::Argv`] built by the pure argv layer. This is
483	    /// the only place `dispatch_registry` touches [`CommandRunner`] --
484	    /// everything about *what* to run (program, args, cwd) was already
485	    /// decided by `registry_argv`.
486	    fn run_argv(&self, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
487	        let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
488	        Ok(self.runner.run(&argv.program, &args, &argv.cwd)?)
489	    }
490	
491	    fn npm_version_is_published(
492	        &self,
493	        package_name: &str,
494	        version: &Version,
495	        registry: Option<&str>,
496	    ) -> Result<bool, GraphError> {
497	        let spec = format!("{package_name}@{}", version.render());
498	        let mut args = vec!["view", spec.as_str(), "--json"];
499	        if let Some(registry) = registry {
500	            args.extend(["--registry", registry]);
501	        }
502	        let output = self
503	            .runner
504	            .run_quiet("npm", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
505	        if output.success() {
506	            return Ok(!output.stdout_trimmed().is_empty());
507	        }
508	        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
509	        if details.contains("e404")
510	            || details.contains("etarget")
511	            || details.contains("no matching version")
512	            || details.contains("is not in this registry")
513	        {
514	            return Ok(false);
515	        }
516	        Err(GraphError::ReleaseIntentStale {
517	            reason: StaleReason::legacy_unclassified(),
518	        })
519	    }
520	
521	    fn dispatch_tag(
522	        &self,
523	        permit: &ApplyPermit,
524	        name: &TagName,
525	        target: &CommitSha,
526	        annotation: &str,
527	    ) -> Result<OperationOutcome, GraphError> {
528	        if let Some(observed) = self.observed_tag(name)? {
529	            return if observed.target == *target && observed.annotation == annotation {
530	                Ok(OperationOutcome::AlreadySatisfied)
531	            } else {
532	                Err(GraphError::ReleaseIntentStale {
533	                    reason: StaleReason::legacy_unclassified(),
534	                })
535	            };
536	        }
537	        // Delegates to `GitAccess::create_tag` rather than inlining `git
538	        // tag` argv, so this inherits its `--` end-of-options separator
539	        // (defends `name` against being misread as a flag) on top of the
540	        // `--no-sign` this durable path has always needed (this repo's CI
541	        // sets `tag.gpgSign`/`commit.gpgsign` globally in some contexts,
542	        // with no tag-signing key available here).
543	        let git = GitAccess::discover(&self.prepared.root, self.runner);
544	        git.create_tag(
545	            name.as_str(),
546	            target,
547	            Some(annotation),
548	            TagSignPolicy::ForceUnsigned,
549	            permit,
550	        )
551	        .map_err(|_error| GraphError::ReleaseIntentStale {
552	            reason: StaleReason::legacy_unclassified(),
553	        })?;
554	        let pushed = self.runner.run(
555	            "git",
556	            &["push", self.checked_git_remote()?.endpoint.as_str(), name.as_str()],
557	            &self.prepared.root,
558	        )?;
559	        if pushed.exit_code != Some(0) {
560	            return Err(GraphError::ReleaseIntentStale {
561	                reason: StaleReason::legacy_unclassified(),
562	            });
563	        }
564	        if self
565	            .observed_tag(name)?
566	            .is_some_and(|observed| observed.target == *target && observed.annotation == annotation)
567	        {
568	            Ok(OperationOutcome::Published)
569	        } else {
570	            Err(GraphError::ReleaseIntentStale {
571	                reason: StaleReason::legacy_unclassified(),
572	            })
573	        }
574	    }
575	
576	    fn dispatch_forge_release(&self, tag: &TagName) -> Result<OperationOutcome, GraphError> {
577	        let remote = self.checked_git_remote()?;
578	        let repository = remote
579	            .github_repository
580	            .as_ref()
581	            .ok_or(GraphError::ReleaseIntentStale {
582	                reason: StaleReason::legacy_unclassified(),
583	            })?
584	            .as_slug();
585	        match self.observed_forge_release_target(tag, &repository)? {
586	            ForgeReleaseObservation::Exact => return Ok(OperationOutcome::AlreadySatisfied),
587	            ForgeReleaseObservation::Conflict => {
588	                return Err(GraphError::ReleaseIntentStale {
589	                    reason: StaleReason::legacy_unclassified(),
590	                })
591	            }
592	            ForgeReleaseObservation::Missing => {}
593	        }
594	        let created = self.runner.run(
595	            "gh",
596	            &[
597	                "release",
598	                "create",
599	                tag.as_str(),
600	                "--repo",
601	                repository.as_str(),
602	                "--verify-tag",
603	                "--generate-notes",
604	            ],
605	            &self.prepared.root,
606	        )?;
607	        if created.exit_code == Some(0)
608	            && self.observed_forge_release_target(tag, &repository)? == ForgeReleaseObservation::Exact
609	        {
610	            Ok(OperationOutcome::Published)
611	        } else {
612	            Err(GraphError::ReleaseIntentStale {
613	                reason: StaleReason::legacy_unclassified(),
614	            })
615	        }
616	    }
617	
618	    fn observed_tag(&self, name: &TagName) -> Result<Option<ObservedTag>, GraphError> {
619	        let reference = format!("refs/tags/{name}^{{commit}}");
620	        let observed = self.runner.run(
621	            "git",
622	            &["rev-parse", "--verify", "--quiet", &reference],
623	            &self.prepared.root,
624	        )?;
625	        if observed.exit_code != Some(0) {
626	            return Ok(None);
627	        }
628	        let target = CommitSha::parse(observed.stdout.trim()).map_err(|_error| GraphError::ReleaseIntentStale {
629	            reason: StaleReason::legacy_unclassified(),
630	        })?;
631	        let details = self.runner.run(
632	            "git",
633	            &[
634	                "for-each-ref",
635	                "--format=%(objecttype)%00%(contents:subject)%00%(contents:body)",
636	                &format!("refs/tags/{name}"),
637	            ],
638	            &self.prepared.root,
639	        )?;
640	        if details.exit_code != Some(0) {
641	            return Err(GraphError::ReleaseIntentStale {
642	                reason: StaleReason::legacy_unclassified(),
643	            });
644	        }
645	        let line = details.stdout.trim_end_matches(['\r', '\n']);
646	        let mut fields = line.split('\0');
647	        let object_type = fields.next();
648	        let annotation = fields.next();
649	        let body = fields.next();
650	        if object_type != Some("tag") || body.is_none_or(|body| !body.trim().is_empty()) || fields.next().is_some() {
651	            return Err(GraphError::ReleaseIntentStale {
652	                reason: StaleReason::legacy_unclassified(),
653	            });
654	        }
655	        let annotation = annotation.ok_or(GraphError::ReleaseIntentStale {
656	            reason: StaleReason::legacy_unclassified(),
657	        })?;
658	        Ok(Some(ObservedTag {
659	            target,
660	            annotation: annotation.to_string(),
661	        }))
662	    }
663	
664	    fn observed_forge_release_target(
665	        &self,
666	        tag: &TagName,
667	        repository: &str,
668	    ) -> Result<ForgeReleaseObservation, GraphError> {
669	        let observed = self.runner.run(
670	            "gh",
671	            &[
672	                "api",
673	                "--include",
674	                "--method",
675	                "GET",
676	                &format!("repos/{repository}/releases/tags/{tag}"),
677	                "--repo",
678	                repository,
679	            ],
680	            &self.prepared.root,
681	        )?;
682	        let (status, body) = parse_github_api_response(&observed.stdout)?;
683	        if status == 404 {
684	            return Ok(ForgeReleaseObservation::Missing);
685	        }
686	        if status != 200 || observed.exit_code != Some(0) {
687	            return Err(GraphError::ReleaseIntentStale {
688	                reason: StaleReason::legacy_unclassified(),
689	            });
690	        }
691	        let value: serde_json::Value = serde_json::from_str(body).map_err(|_error| GraphError::ReleaseIntentStale {
692	            reason: StaleReason::legacy_unclassified(),
693	        })?;
694	        let expected = match &self.prepared.source {
695	            SourceIdentity::GitCommit { sha } => sha.as_str(),
696	            SourceIdentity::HermeticContent { .. } => {
697	                return Err(GraphError::ReleaseIntentStale {
698	                    reason: StaleReason::legacy_unclassified(),
699	                })
700	            }
701	        };
702	        Ok(
703	            if value.get("tag_name").and_then(serde_json::Value::as_str) == Some(tag.as_str())
704	                && value.get("target_commitish").and_then(serde_json::Value::as_str) == Some(expected)
705	            {
706	                ForgeReleaseObservation::Exact
707	            } else {
708	                ForgeReleaseObservation::Conflict
709	            },
710	        )
711	    }
712	
713	    fn checked_git_remote(&self) -> Result<&PreparedGitRemote, GraphError> {
714	        let expected = self
715	            .prepared
716	            .git_remote
717	            .as_ref()
718	            .ok_or(GraphError::ReleaseIntentStale {
719	                reason: StaleReason::legacy_unclassified(),
720	            })?;
721	        if prepared_git_remote(&self.prepared.root, self.runner)? != *expected {
722	            return Err(GraphError::ReleaseIntentStale {
723	                reason: StaleReason::git_remote_changed(),
724	            });
725	        }
726	        Ok(expected)
727	    }
728	}
729	
730	fn parse_github_api_response(stdout: &str) -> Result<(u16, &str), GraphError> {
731	    let (headers, body) = stdout
732	        .rsplit_once("\r\n\r\n")
733	        .or_else(|| stdout.rsplit_once("\n\n"))
734	        .ok_or(GraphError::ReleaseIntentStale {
735	            reason: StaleReason::legacy_unclassified(),
736	        })?;
737	    let status_line = headers
738	        .lines()
739	        .rev()
740	        .find(|line| line.trim_end_matches('\r').starts_with("HTTP/"))
741	        .ok_or(GraphError::ReleaseIntentStale {
742	            reason: StaleReason::legacy_unclassified(),
743	        })?;
744	    let status = status_line
745	        .split_whitespace()
746	        .nth(1)
747	        .ok_or(GraphError::ReleaseIntentStale {
748	            reason: StaleReason::legacy_unclassified(),
749	        })?
750	        .parse::<u16>()
751	        .map_err(|_error| GraphError::ReleaseIntentStale {
752	            reason: StaleReason::legacy_unclassified(),
753	        })?;
754	    Ok((status, body))
755	}
