793	fn derive_release_inputs<R: CommandRunner, D: DependencyResolver>(
794	    workspace: &Workspace<'_, R, D>,
795	    decision: &ReleaseDecisionV1,
796	    source: SourceIdentity,
797	) -> Result<DerivedReleaseInputs, GraphError> {
798	    let mut package_inputs = Vec::new();
799	
800	    let mut selected = BTreeMap::new();
801	    let mut package_ids = BTreeMap::<callisto_model::PackageId, Vec<ReleasePackageId>>::new();
802	    for package in workspace.graph.packages() {
803	        // One canonical manifest per ecosystem is the expected shape, but
804	        // dedup defensively -- `release_package_ids` maps every canonical
805	        // manifest, and two manifests sharing an ecosystem would otherwise
806	        // select/push the same identity twice.
807	        for id in super::release_decision::release_package_ids(package)?
808	            .into_iter()
809	            .collect::<BTreeSet<_>>()
810	        {
811	            if let Some(entry) = decision.entries.iter().find(|entry| entry.package == id) {
812	                selected.insert(id.clone(), (package, entry.target_version.clone()));
813	                package_ids.entry(package.id.clone()).or_default().push(id);
814	            }
815	        }
816	    }
817	    for entry in &decision.entries {
818	        let id = &entry.package;
819	        if !selected.contains_key(id) {
820	            return Err(GraphError::ReleasePackageNotSelected { package: id.clone() });
821	        }
822	    }
823	
824	    let requires_git_remote = selected.values().any(|(package, _)| {
825	        package
826	            .publish_to
827	            .iter()
828	            .any(|target| !matches!(target, PublishTarget::None))
829	    });
830	    let git_remote = requires_git_remote
831	        .then(|| prepared_git_remote(&workspace.root, workspace.runner))
832	        .transpose()?;
833	
834	    let mut operations = BTreeMap::<ReleaseOperationId, ReleaseOperation>::new();
835	    let mut prepared = BTreeMap::<ReleaseOperationId, PreparedOperation>::new();
836	    let mut publishes_by_package = BTreeMap::<ReleasePackageId, Vec<ReleaseOperationId>>::new();
837	    let mut tag_by_package = BTreeMap::<ReleasePackageId, ReleaseOperationId>::new();
838	
839	    // First construct leaves so dependency prerequisites can refer only to
840	    // exact selected release identities, never PackageId's wildcard matcher.
841	    for (id, (package, version)) in &selected {
842	        let produces_tag = package
843	            .publish_to
844	            .iter()
845	            .any(|target| !matches!(target, PublishTarget::None));
846	        let fingerprint = package_fingerprint(
847	            workspace,
848	            id,
849	            package,
850	            version,
851	            produces_tag.then_some(git_remote.as_ref()).flatten(),
852	        )?;
853	        package_inputs.push(ReleasePackageInputV1 {
854	            package: id.clone(),
855	            fingerprint,
856	        });
857	
858	        let mut publishes = Vec::new();
859	        for target in &package.publish_to {
860	            if target.ecosystem() == Some(id.ecosystem()) {
861	                let registry_key = target.registry_key().expect("registry target has registry key");
862	                let binding = prepared_registry_binding(workspace, target)?;
863	                let operation = ReleaseOperation::registry_publish(
864	                    id.clone(),
865	                    version.clone(),
866	                    RegistryBindingId::new(registry_key.as_str(), binding.identity.clone()).map_err(|_error| {
867	                        GraphError::ReleaseIntentStale {
868	                            reason: StaleReason::legacy_unclassified(),
869	                        }
870	                    })?,
871	                    Vec::new(),
872	                )
873	                .map_err(|_error| GraphError::ReleaseIntentStale {
874	                    reason: StaleReason::legacy_unclassified(),
875	                })?;
876	                // A durable registry operation must have one exact endpoint
877	                // binding. The model-level operation identity currently has
878	                // only a registry key, so reject a second target that would
879	                // collapse to the same operation until the typed binding
880	                // identity is added there.
881	                if prepared.contains_key(operation.id()) {
882	                    return Err(GraphError::ReleaseIntentStale {
883	                        reason: StaleReason::legacy_unclassified(),
884	                    });
885	                }
886	                prepared.insert(
887	                    operation.id().clone(),
888	                    PreparedOperation::RegistryPublish {
889	                        package_dir: package_dir(package)?,
890	                        package_name: id.name().to_string(),
891	                        version: version.clone(),
892	                        registry: binding,
893	                        npm_access: match target {
894	                            PublishTarget::Npm { access, .. } => *access,
895	                            _ => None,
896	                        },
897	                        npm_tag: matches!(target, PublishTarget::Npm { .. })
898	                            .then(|| version.is_prerelease().then_some("next".to_string()))
899	                            .flatten(),
900	                    },
901	                );
902	                publishes.push(operation.id().clone());
903	                operations.insert(operation.id().clone(), operation);
904	            }
905	        }
906	        publishes.sort();
907	        publishes_by_package.insert(id.clone(), publishes);
908	    }
909	
910	    // Replace each publish leaf with prerequisites from selected dependency
911	    // packages. This preserves the existing publish semantics: runtime,
912	    // build, optional, and dev dependencies must exist before publish.
913	    for (id, (package, _)) in &selected {
914	        let mut prerequisites = BTreeSet::new();
915	        for edge in workspace.graph.dependencies_of(&package.id) {
916	            if !matches!(
917	                edge.kind,
918	                DepKind::Runtime | DepKind::Build | DepKind::Optional | DepKind::Dev
919	            ) {
920	                continue;
921	            }
922	            for dependency_release_id in package_ids.get(&edge.to).into_iter().flatten() {
923	                prerequisites.extend(
924	                    publishes_by_package
925	                        .get(dependency_release_id)
926	                        .into_iter()
927	                        .flatten()
928	                        .cloned(),
929	                );
930	            }
931	        }
932	        for publish_id in publishes_by_package.get(id).into_iter().flatten() {
933	            let operation = operations.get(publish_id).expect("publish operation was constructed");
934	            let replacement = ReleaseOperation::new(operation.id().clone(), prerequisites.iter().cloned().collect())
935	                .map_err(|_error| GraphError::ReleaseIntentStale {
936	                    reason: StaleReason::legacy_unclassified(),
937	                })?;
938	            operations.insert(publish_id.clone(), replacement);
939	        }
940	    }
941	
942	    for (id, (package, version)) in &selected {
943	        if !package
944	            .publish_to
945	            .iter()
946	            .any(|target| !matches!(target, PublishTarget::None))
947	        {
948	            continue;
949	        }
950	        let tag = ReleaseOperation::tag(
951	            id.clone(),
952	            version.clone(),
953	            publishes_by_package.get(id).cloned().unwrap_or_default(),
954	        )
955	        .map_err(|_error| GraphError::ReleaseIntentStale {
956	            reason: StaleReason::legacy_unclassified(),
957	        })?;
958	        let tag_name = package
959	            .tag_template
960	            .clone()
961	            .unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))
962	            .render(version);
963	        let target = match &source {
964	            SourceIdentity::GitCommit { sha } => sha.clone(),
965	            SourceIdentity::HermeticContent { .. } => {
966	                return Err(GraphError::ReleaseIntentStale {
967	                    reason: StaleReason::legacy_unclassified(),
968	                })
969	            }
970	        };
971	        prepared.insert(
972	            tag.id().clone(),
973	            PreparedOperation::Tag {
974	                annotation: format!("Release {tag_name}"),
975	                name: tag_name,
976	                target,
977	            },
978	        );
979	        tag_by_package.insert(id.clone(), tag.id().clone());
980	        operations.insert(tag.id().clone(), tag);
981	    }
982	    for (id, (package, version)) in &selected {
983	        if package
984	            .publish_to
985	            .iter()
986	            .any(|target| matches!(target, PublishTarget::GitHubRelease))
987	        {
988	            let tag = tag_by_package.get(id).expect("release point has tag").clone();
989	            let operation =
990	                ReleaseOperation::forge_release(id.clone(), version.clone(), vec![tag]).map_err(|_error| {
991	                    GraphError::ReleaseIntentStale {
992	                        reason: StaleReason::legacy_unclassified(),
993	                    }
994	                })?;
995	            let tag = match prepared.get(operation.prerequisites().first().expect("forge release has tag")) {
996	                Some(PreparedOperation::Tag { name, .. }) => name.clone(),
997	                _ => {
998	                    return Err(GraphError::ReleaseIntentStale {
999	                        reason: StaleReason::legacy_unclassified(),
1000	                    })
1001	                }
1002	            };
1003	            prepared.insert(operation.id().clone(), PreparedOperation::ForgeRelease { tag });
1004	            operations.insert(operation.id().clone(), operation);
1005	        }
1006	    }
1007	
1008	    Ok((
1009	        ReleaseInputSnapshotV1::new(source, package_inputs).map_err(|_error| GraphError::ReleaseIntentStale {
1010	            reason: StaleReason::legacy_unclassified(),
1011	        })?,
1012	        canonical_operation_order(operations)?,
1013	        prepared,
1014	        git_remote,
1015	    ))
1016	}
