1084	fn canonical_operation_order(
1085	    operations: BTreeMap<ReleaseOperationId, ReleaseOperation>,
1086	) -> Result<Vec<ReleaseOperation>, GraphError> {
1087	    let mut remaining: BTreeMap<_, usize> = operations
1088	        .iter()
1089	        .map(|(id, operation)| (id.clone(), operation.prerequisites().len()))
1090	        .collect();
1091	    let mut dependents = BTreeMap::<ReleaseOperationId, Vec<ReleaseOperationId>>::new();
1092	    for (id, operation) in &operations {
1093	        for prerequisite in operation.prerequisites() {
1094	            dependents.entry(prerequisite.clone()).or_default().push(id.clone());
1095	        }
1096	    }
1097	    let mut ready: BTreeSet<_> = remaining
1098	        .iter()
1099	        .filter_map(|(id, count)| (*count == 0).then_some(id.clone()))
1100	        .collect();
1101	    let mut ordered = Vec::with_capacity(operations.len());
1102	    while let Some(id) = ready.pop_first() {
1103	        ordered.push(operations.get(&id).expect("known operation").clone());
1104	        for dependent in dependents.get(&id).into_iter().flatten() {
1105	            let count = remaining.get_mut(dependent).expect("known operation");
1106	            *count -= 1;
1107	            if *count == 0 {
1108	                ready.insert(dependent.clone());
1109	            }
1110	        }
1111	    }
1112	    if ordered.len() != operations.len() {
1113	        return Err(GraphError::ReleaseIntentStale {
1114	            reason: StaleReason::legacy_unclassified(),
1115	        });
1116	    }
1117	    Ok(ordered)
1118	}
