        let state_dir = tempfile::tempdir().unwrap();
        let locator = crate::IgnoreWalkLocator::new(dir.path());
        let intent = build_release_intent(
            dir.path(),
            &locator,
            &runner,
            &decision(),
            ExecutionTrustProfileV1::GitCommit,
